let P,C,issues,coverage;try{[P,C,issues,coverage]=await Promise.all(['pages','chapters','corrections','coverage'].map(n=>fetch('/data/'+n+'.json').then(r=>{if(!r.ok)throw Error(n);return r.json()})));}catch{ $('#app').innerHTML='<main class="card"><h1>Content load হয়নি</h1><p>সংযোগ পরীক্ষা করে page reload করুন।</p><button onclick="location.reload()">Reload</button></main>';throw Error('Content unavailable');}
let S=read(),view='study',mode='brief',step=0,lab='convert',labInputs=null,labOutput=null,mathStep=0,allSteps=false,qIndex=0,qFilter='',difficulty='',checked=false,selected=null,flashIndex=0,flipped=false,exampleQuery='',exampleType='',mock=null,mockIdx=0,showMockResults=false;
const initial=new URLSearchParams(location.hash.slice(1));if(+initial.get('page')>=1&&+initial.get('page')<=55)S.page=+initial.get('page');
function persist(){if(!save(S))toast('Progress save হয়নি। Export করুন।');}
function toast(t){$('.toast')?.remove();let d=document.createElement('div');d.className='toast';d.role='status';d.textContent=t;document.body.append(d);setTimeout(()=>d.remove(),3500);}
const chapter=p=>C[P[p-1].chapter],toggle=(key,value)=>{S[key]=S[key].includes(value)?S[key].filter(x=>x!==value):[...S[key],value];persist();};
