const art=`<svg viewBox="0 0 190 160" role="img" aria-label="Four-bit logic circuit"><g fill="none" stroke="#80a58c" stroke-width="1.2"><rect x="52" y="27" width="88" height="98" rx="14"/><path d="M20 48h32m-32 24h32m-32 24h32m88-48h30m-30 24h30m-30 24h30M73 8v19m24-19v19m24-19v19M73 125v20m24-20v20m24-20v20"/><circle cx="96" cy="75" r="26" stroke-dasharray="2 5"/></g><text x="96" y="81" fill="#deeca8" font-size="18" text-anchor="middle" font-family="monospace">1010</text><g fill="#d3e99d"><circle cx="20" cy="48" r="4"/><circle cx="20" cy="72" r="4"/><circle cx="20" cy="96" r="4"/><circle cx="170" cy="48" r="4"/><circle cx="170" cy="72" r="4"/><circle cx="170" cy="96" r="4"/></g></svg>`;
function hero(ey,title,sub,meta='55 original pages · বাংলা + English · Learn at your pace'){return `<section class="hero"><div><div class="eyebrow">${ey}</div><h1>${title}</h1><p>${sub}</p>${meta.split(' · ').map(x=>`<span class="pill">${esc(x)}</span>`).join('')}</div><div class="heroart">${art}</div></section>`;}
function bindPages(root=document){root.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{go(+b.dataset.page);$('#dialog')?.close()});}
function go(p){if(!Number.isInteger(p)||p<1||p>55)return;S.page=p;view='study';step=0;persist();history.replaceState(null,'','#page='+p);shell();window.scrollTo(0,0);}
function shell(){document.body.classList.toggle('dark',S.dark);document.documentElement.style.setProperty('--size',S.font+'px');$('#app').innerHTML=`<div class="shell"><aside class="sidebar" aria-label="Chapter navigation"><button class="mobileclose" aria-label="Close chapter menu">✕</button><div class="brand"><span class="logo">⌘</span><div>IT PATH<small>বাংলা EXAM ACADEMY</small></div></div><div class="sideprogress"><div style="display:flex;justify-content:space-between"><b>Your learning journey</b><span>${S.done.length}/55</span></div><div class="track"><i style="width:${S.done.length/55*100}%"></i></div>${Math.round(S.done.length/55*100)}% complete · এক ধাপ করে এগিয়ে যান</div><div class="caption">Your book · 8 parts</div>${C.map(([name,start,end],i)=>`<details class="chapter" ${P[S.page-1].chapter===i?'open':''}><summary>${esc(name)} <small>${Math.round(S.done.filter(p=>p>=start&&p<=end).length/(end-start+1)*100)}%</small></summary>${P.filter(p=>p.chapter===i).map(p=>`<button data-page="${p.id}" class="pagelink ${S.page===p.id?'active':''}"><span>${S.done.includes(p.id)?'✓':String(p.id).padStart(2,'0')}</span>${esc(p.title)}${S.marks.includes(p.id)?' ☆':''}</button>`).join('')}</details>`).join('')}<div class="actions"><button id="bookmarks">☆ Bookmarks</button></div><div class="sidefoot">CRACK THE IT WRITTEN<br>Linux · Digital logic · K-map<br>Assembly · Software engineering</div></aside><div class="workspace"><header class="topbar"><button class="menu" aria-label="Open chapter menu">☰</button><div class="breadcrumb">My academy <span style="margin:0 9px">/</span><b>IT Written</b></div><form class="search" id="search"><span aria-hidden="true">⌕</span><input id="query" type="search" aria-label="Search academy" placeholder="Search বাংলা, topic, formula, page…"><button aria-label="Run search">↵</button></form><div class="topactions"><button id="font" aria-label="Change font size">Aa</button><button id="theme" aria-label="Toggle dark mode">${S.dark?'☀':'◐'}</button></div><span class="avatar">YOU</span></header><nav class="nav" aria-label="Academy sections">${[['study','▤ Page study'],['lab','∑ Math lab'],['examples','◇ Examples'],['diagrams','⌘ Diagrams'],['practice','✓ Practice'],['written','✎ Original bank'],['mock','◷ Mock test'],['revision','↻ Revision'],['dashboard','◎ My progress'],['coverage','▧ Source audit']].map(([v,t])=>`<button data-view="${v}" class="${view===v?'active':''}">${t}</button>`).join('')}</nav><main class="content" id="main"></main></div></div><dialog id="dialog"><div class="dialoghead"><strong id="dialog-title"></strong><button id="close-dialog" aria-label="Close dialog">✕ Close</button></div><div id="dialog-body"></div></dialog>`;
bindPages();$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;shell()});$('.menu').onclick=()=>$('.sidebar').classList.add('open');$('.mobileclose').onclick=()=>$('.sidebar').classList.remove('open');$('#theme').onclick=()=>{S.dark=!S.dark;persist();shell()};$('#font').onclick=()=>{S.font=S.font>=22?16:S.font+1;persist();document.documentElement.style.setProperty('--size',S.font+'px');toast('Font size '+S.font+'px')};$('#search').onsubmit=e=>{e.preventDefault();search($('#query').value)};$('#close-dialog').onclick=()=>$('#dialog').close();$('#bookmarks').onclick=()=>{dialog('Saved bookmarks',S.marks.length?S.marks.map(id=>`<button class="option" data-page="${id}">PDF ${id} · ${esc(P[id-1].title)}</button>`).join(''):'<p class="empty">এখনো bookmark নেই। Topic-এ ☆ Save চাপুন।</p>');bindPages($('#dialog-body'))};render();}
function dialog(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;if(!$('#dialog').open)$('#dialog').showModal();}
function source(p=S.page){dialog('Original source · PDF '+p,`<p class="meta">Printed page ${P[p-1].printed??'not numbered'} · Original material, unchanged.</p><div class="actions"><a href="/book.pdf#page=${p}" target="_blank" rel="noopener">Open original PDF ↗</a><a href="/page-images/page-${String(p).padStart(2,'0')}.jpg" target="_blank" rel="noopener">Full image ↗</a></div><img class="source-img" src="/page-images/page-${String(p).padStart(2,'0')}.jpg" alt="Original book PDF page ${p}" loading="lazy">`);}
function render(){({study:study,lab:labView,examples:exampleView,diagrams:diagramView,practice:practiceView,written:writtenView,mock:mockView,revision:revisionView,dashboard:dashboardView,coverage:coverageView}[view]||study)();}
function study(){let p=P[S.page-1],localIssues=issues.filter(i=>i[0]===p.id),relevant=examples.filter(e=>e.page===p.id);$('#main').innerHTML=hero('YOUR PERSONAL IT WRITTEN STUDY COMPANION','বুঝে শিখুন। আত্মবিশ্বাসে লিখুন।','From your first Linux command to your final K-map. ছোট ছোট ধাপে, নিজের গতিতে—প্রতিটি পৃষ্ঠার পাশে সহজ ব্যাখ্যা।')+`<div class="studygrid"><section><div class="meta">${esc(chapter(p.id)[0])} <span style="margin:0 8px">/</span> PDF page ${p.id} of 55</div><article class="card"><div class="cardhead"><div><span class="tag">PAGE ${String(p.id).padStart(2,'0')} · STUDY NOTES</span><h2 style="margin-top:14px">${esc(p.bn)}</h2><div class="meta">${esc(p.title)} · PDF ${p.id} · Printed ${p.printed??'not numbered'}</div></div><button id="bookmark">${S.marks.includes(p.id)?'★ Saved':'☆ Save'}</button></div><div class="modes" role="group" aria-label="Reading mode">${[['brief','Brief · সংক্ষেপে'],['guided','Guided · ধাপে ধাপে'],['full','Full · বিস্তারিত']].map(([m,t])=>`<button data-mode="${m}" class="${mode===m?'active':''}" aria-pressed="${mode===m}">${t}</button>`).join('')}</div><div id="lesson-body"></div><div class="callout"><b>মনে রাখার সহজ উপায়</b><br>${esc(p.memory)}</div><details class="concept"><summary>Recall: ${esc((questions.find(q=>q.page===p.id)||questions.find(q=>P[q.page-1].chapter===p.chapter))?.q||"এই topic-এর মূল নিয়ম কী?")}</summary><p>${esc((questions.find(q=>q.page===p.id)||questions.find(q=>P[q.page-1].chapter===p.chapter))?.explanation||p.points[0])}</p></details><div class="actions"><button class="primary" id="complete">${S.done.includes(p.id)?'✓ Completed · Undo':'✓ Mark as learned'}</button><button id="difficult">${S.difficult.includes(p.id)?'● Difficult saved':'⚑ Needs revision'}</button><button id="source">▧ Original page</button></div></article>${localIssues.length?`<section class="card"><h3>Source integrity · সংশোধন ও সতর্কতা</h3>${localIssues.map(i=>`<div class="callout warning"><b>Original:</b> ${esc(i[1])}<br><b>Correction / qualification:</b> ${esc(i[2])}</div>`).join('')}</section>`:''}${relevant.length?`<section class="card"><h3>Worked examples · এই পৃষ্ঠার অঙ্ক</h3>${relevant.map(e=>`<button class="option" data-example="${e.id}">${esc(e.title)} <small>→ 10-step solution</small></button>`).join('')}</section>`:''}<section class="card"><h3>আপনার নিজের নোট</h3><p class="meta">শুধু এই browser-এ থাকে। নিয়মিত progress export করুন।</p><label for="notes">Page ${p.id} notes</label><textarea id="notes" placeholder="আপনার ভাষায় লিখুন…">${esc(S.notes[p.id]||'')}</textarea><small id="note-status" role="status"></small></section><section class="card page-controls"><button id="previous" ${p.id===1?'disabled':''}>← Previous</button><form id="jump"><label style="display:inline" for="jump-page">PDF page </label><input id="jump-page" type="number" min="1" max="55" value="${p.id}" required><button>Go</button></form><button id="next" ${p.id===55?'disabled':''}>Next →</button></section></section><aside class="right"><div class="card"><span class="tag">TODAY’S FOCUS</span><h3 style="margin-top:17px">Read. Recall. Repeat.</h3><p>একটি ধারণা বুঝুন। উত্তর না দেখে বলুন। ভুল হলে আবার চেষ্টা করুন।</p><div class="track"><i style="width:${S.done.length/55*100}%"></i></div><small>${S.done.length} of 55 pages completed</small></div><div class="card"><h3>Essential formula</h3><div class="formula">${math(p.chapter===4?'2^n\\text{ cells}':p.chapter===6?'2^n\\text{ addresses}':p.chapter===7?'E(C)=\\sum p_i C_i':'N=\\sum d_i b^i')}</div><p>চিহ্ন ও ধাপসহ অনুশীলন করতে Math lab খুলুন।</p><button id="openlab">Open math lab ↗</button></div><div class="card"><h3>Source at your side</h3><p>প্রতিটি original page অক্ষত রাখা আছে। বিশেষ করে complement bar ও circuit-এর জন্য image মিলিয়ে পড়ুন।</p><button id="source-right">Compare original ↗</button></div><div class="card"><h3>আরও শেখার সহায়তা</h3><a target="_blank" rel="noopener" href="https://www.youtube.com/results?search_query=${encodeURIComponent(p.title+' Bangla tutorial')}">YouTube Search · ${esc(p.title)} ↗</a><p class="meta" style="margin-top:10px">Search link; direct video verified নয়।</p></div></aside></div><div class="footer">Teaching notes are newly authored. Original wording and diagrams remain in the source. Source coverage and verification limits are in Source audit.</div>`;
lessonBody();$$('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;step=0;study()});$('#bookmark').onclick=()=>{toggle('marks',p.id);shell()};$('#complete').onclick=()=>{toggle('done',p.id);shell()};$('#difficult').onclick=()=>{toggle('difficult',p.id);study()};$('#source').onclick=$('#source-right').onclick=()=>source();$('#openlab').onclick=()=>{view='lab';shell()};$('#previous').onclick=()=>go(p.id-1);$('#next').onclick=()=>go(p.id+1);$('#jump').onsubmit=e=>{e.preventDefault();go(+$('#jump-page').value)};$('#notes').oninput=()=>{S.notes[p.id]=$('#notes').value;persist();$('#note-status').textContent='Saved locally ✓'};bindExamples();}
function lessonBody(){let p=P[S.page-1];if(mode==='brief')$('#lesson-body').innerHTML=`<p class="lead">${esc(p.intro)}</p><h3>যা মনে রাখবেন</h3>${p.points.map(t=>`<details class="concept"><summary>${esc(t)}</summary><p>${esc(p.memory)}। এই বিষয়টি মূল পৃষ্ঠা ${p.id}-এর সঙ্গে মিলিয়ে পড়ুন।</p></details>`).join('')}`;
if(mode==='guided'){let steps=[p.intro,...p.points];step=Math.min(step,steps.length-1);$('#lesson-body').innerHTML=`<div class="steps"><div class="stephead"><span>PERSONAL TUTOR</span><span>Step ${step+1} of ${steps.length}</span></div><div class="track"><i style="width:${(step+1)/steps.length*100}%"></i></div><p class="lead">${esc(steps[step])}</p><details class="concept"><summary>Hint দেখুন</summary><p>${esc(p.memory)}। এই ধাপটি নিজের ভাষায় ব্যাখ্যা করে পরের ধাপে যান।</p></details><div class="actions"><button id="guideprev" ${step===0?'disabled':''}>← Previous</button><button class="primary" id="guidenext" ${step===steps.length-1?'disabled':''}>Next step →</button><button id="guiderestart">Restart</button></div></div>`;$('#guideprev').onclick=()=>{step--;lessonBody()};$('#guidenext').onclick=()=>{step++;lessonBody()};$('#guiderestart').onclick=()=>{step=0;lessonBody()};}
if(mode==='full')$('#lesson-body').innerHTML=`<p class="lead">${esc(p.intro)}</p><h3>ধারণা ও প্রয়োগ</h3>${p.points.map((t,i)=>`<section class="concept"><h3>${i+1}. ${esc(t)}</h3></section>`).join('')}<h3>Source subsections</h3>${p.sections.length?`<ul>${p.sections.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:'<p class="meta">এই পৃষ্ঠায় আলাদা numbered subsection নেই।</p>'}<div class="callout warning">Extracted text-এ overbar হারাতে পারে। নিচের মূল image-ই source expression-এর নির্ভরযোগ্য reference। বাংলা notes একটি page-level guide; প্রতিটি source paragraph-এর পূর্ণ অনুবাদ নয়।</div><details class="concept"><summary>Original page · diagrams, tables, questions</summary><img class="source-img" loading="lazy" src="/page-images/page-${String(p.id).padStart(2,'0')}.jpg" alt="Original PDF page ${p.id}"><a href="/book.pdf#page=${p.id}" target="_blank" rel="noopener">Open PDF page ${p.id}</a></details><details class="concept" open><summary>Complete original text · English source reference</summary><pre class="source-text">${esc(p.text)}</pre></details>`;}
function bindExamples(){ $$('[data-example]').forEach(b=>b.onclick=()=>openExample(+b.dataset.example)); }
function openExample(id){let e=examples.find(e=>e.id===id);lab=e.type;labInputs={...e.inputs};mathStep=0;allSteps=false;view='lab';shell();toast('PDF '+e.page+' · '+e.title);}
function field(k,label,v){let choices={from:[2,8,10,16],to:[2,8,10,16],mode:['SOP','POS'],op:['add','subtract'],kind:['bcd','excess3','parity','ascii']};return `<label>${esc(label)}${choices[k]?`<select name="${k}">${choices[k].map(a=>`<option ${String(a)===String(v)?'selected':''}>${a}</option>`).join('')}</select>`:`<input name="${k}" value="${esc(v)}" ${['width','n','bits','buy','p1','p2','c1','c2','d1','d2'].includes(k)?'type="number" step="any"':'type="text"'} ${k==='dont'?'':'required'}>`}</label>`;}
function labView(){let l=labs[lab],values=labInputs||Object.fromEntries(Object.entries(l.fields).map(([k,v])=>[k,v[1]]));$('#main').innerHTML=hero('INTERACTIVE MATHEMATICS LAB','অঙ্কের প্রতিটি ধাপ বুঝুন।','নিজে মান বসান, উত্তর বদলান, আর প্রতিটি নিয়ম কেন লাগছে তা দেখুন। Source problem বা নিজের উদাহরণ—দুটিই অনুশীলন করুন।')+`<div class="filters"><label>Choose a calculator<select id="labselect">${Object.entries(labs).map(([k,v])=>`<option value="${k}" ${lab===k?'selected':''}>${v.title}</option>`).join('')}</select></label></div><div class="studygrid"><section><div class="card"><span class="tag">LIVE CALCULATOR · ${esc(l.title)}</span><h2 style="margin-top:15px">${esc(l.title)}</h2><form id="labform"><div class="formgrid">${Object.entries(l.fields).map(([k,[label,v]])=>field(k,label,values[k]??v)).join('')}</div><div class="actions"><button class="primary">Calculate / Recalculate</button><button type="button" id="labreset">Reset example</button></div></form><div id="laberror" role="alert"></div></div><div id="labresult"></div></section><aside class="right"><div class="card"><h3>Formula & assumptions</h3><p>${esc(l.rule)}</p><div class="callout">${esc(l.symbols)}</div><p class="meta">${esc(l.units)}</p></div><div class="card"><h3>Source examples</h3>${examples.filter(e=>e.type===lab).map(e=>`<button class="option" data-example="${e.id}">${esc(e.title)}<br><small>PDF ${e.page} · Printed ${P[e.page-1].printed??'—'}</small></button>`).join('')}</div></aside></div>`;
$('#labselect').onchange=()=>{lab=$('#labselect').value;labInputs=null;mathStep=0;allSteps=false;labView()};$('#labreset').onclick=()=>{labInputs=null;mathStep=0;allSteps=false;labView()};$('#labform').onsubmit=e=>{e.preventDefault();calculate()};$('#labform').onchange=()=>calculate();bindExamples();calculate();}
function calculate(){let data=Object.fromEntries(new FormData($('#labform')));labInputs=data;try{let out;switch(lab){case'convert':out=M.convert(data.value,+data.from,+data.to);break;case'complement':out=M.complement(+data.value,+data.width);break;case'binary':out=M.binaryArithmetic(data.a,data.b,data.op);break;case'codes':out=M.codes(data.value,data.kind);break;case'bcdAdd':out=M.bcdAdd(data.a,data.b);break;case'kmap':out=M.minimize(+data.n,data.values,data.dont,data.mode);break;case'boolean':out=M.boolean(data.expression);break;case'capacity':out=M.capacity(data.bits);break;case'counter':out=M.counter(data.n);break;case'expected':out=M.expected(...['buy','p1','c1','c2','p2','d1','d2'].map(k=>data[k]));}labOutput=out;$('#laberror').innerHTML='';mathStep=0;mathResult();}catch(e){$('#laberror').innerHTML=`<div class="callout warning">${esc(e.message)}</div>`;$('#labresult').innerHTML='';labOutput=null;}}
function mapHTML(o){let gray=[0,1,3,2],rows=o.n===4?gray:[0,1],cols=o.n===2?[0,1]:gray,cb=o.n===2?1:2;return `<div class="scroll"><table class="kmap" aria-label="Karnaugh map in Gray-code order"><thead><tr><th>Row / Col</th>${cols.map(c=>`<th>${c.toString(2).padStart(cb,'0')}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th>${r.toString(2).padStart(o.n-cb,'0')}</th>${cols.map(c=>{let i=r*2**cb+c,v=o.dc.includes(i)?'X':o.mode==='SOP'?+o.target.includes(i):+!o.target.includes(i);return `<td data-cell="${i}" class="${v==='X'?'x':v?'on':''}"><small>m${i}</small><b>${v}</b></td>`}).join('')}</tr>`).join('')}</tbody></table></div>`;}
function mathResult(){let o=labOutput,l=labs[lab],steps=M.tenSteps(l.title,Object.entries(labInputs).map(([k,v])=>`${k} = ${v||'none'}`).join('; '),l,o);$('#labresult').innerHTML=`<section class="card"><span class="tag">RECALCULATED RESULT</span><p class="result" style="margin-top:15px">${esc(o.result)}</p>${o.approx?'<div class="callout warning">Fraction truncated: displayed digits approximate the value.</div>':''}${o.truth?mapHTML(o)+`<div class="actions">${o.groups.map((g,i)=>`<button data-group="${i}">Group ${i+1}: ${esc(g.term)}</button>`).join('')}<button id="clear-groups">Clear highlights</button></div><p class="meta">Click a group to highlight its cells. Minimized over all specified input rows.</p>`:''}<div class="steps"><div class="stephead"><span>GUIDED SOLUTION</span><span>Step ${mathStep+1} of 10</span></div><div class="track"><i style="width:${(mathStep+1)*10}%"></i></div>${(allSteps?steps:[steps[mathStep]]).map(([title,text])=>`<section><h3>${esc(title)}</h3><pre>${esc(text)}</pre></section>`).join('')}<div class="actions"><button id="mprev" ${mathStep===0?'disabled':''}>← Previous Step</button><button class="primary" id="mnext" ${mathStep===9?'disabled':''}>Next Step →</button><button id="mrestart">Restart</button><button id="mall">${allSteps?'Hide Steps':'Show All Steps'}</button></div><details class="concept"><summary>Show Hint</summary><p>${esc(l.rule)}</p></details><details class="concept"><summary>Expand Detailed Explanation</summary><p>প্রথমে input-এর base, bit width বা unit শনাক্ত করি। নিয়মটি নেওয়া হয় কারণ input এই model-এর শর্ত পূরণ করছে। Calculate ধাপে প্রতিটি মান মূল input থেকে নেওয়া। Output যাচাইয়ে representation, truth table অথবা independent decimal comparison ব্যবহার করা হয়েছে।</p><p>${esc(l.units)}</p></details></div><div class="actions"><button id="another">Try Another Example</button><button id="self-practice">Practice Yourself</button></div>${o.truth?`<details class="concept"><summary>Verification · complete truth table</summary><div class="scroll"><table class="data"><tr><th>Input</th><th>Original</th><th>Result</th><th>Check</th></tr>${o.truth.map(t=>`<tr><td>${t.bits}</td><td>${t.expected}</td><td>${t.result}</td><td>${t.ok?'✓':'✕'}</td></tr>`).join('')}</table></div></details>`:''}</section>`;$('#mprev').onclick=()=>{mathStep--;allSteps=false;mathResult()};$('#mnext').onclick=()=>{mathStep++;allSteps=false;mathResult()};$('#mrestart').onclick=()=>{mathStep=0;allSteps=false;mathResult()};$('#mall').onclick=()=>{allSteps=!allSteps;mathResult()};$('#another').onclick=()=>{let e=examples.filter(x=>x.type===lab);openExample(e[Math.floor(Math.random()*e.length)].id)};$('#self-practice').onclick=()=>{toast('Input বদলে আগে নিজে হিসাব করুন, তারপর Calculate দিয়ে মিলিয়ে নিন।');$('#labform input')?.focus()};$$('[data-group]').forEach(b=>b.onclick=()=>{$$('[data-cell]').forEach(c=>c.classList.toggle('selected',o.groups[+b.dataset.group].cells.includes(+c.dataset.cell)))});if($('#clear-groups'))$('#clear-groups').onclick=()=>$$('[data-cell]').forEach(c=>c.classList.remove('selected'));}
function exampleView(){let matches=examples.filter(e=>(!exampleType||e.type===exampleType)&&(e.title+' '+e.page+' '+e.type+' '+e.difficulty).toLowerCase().includes(exampleQuery.toLowerCase()));$('#main').innerHTML=hero('SEARCHABLE WORKED-EXAMPLE LIBRARY','সমাধান দেখুন। তারপর নিজে করুন।',`${examples.length} source-linked numerical illustrations and worked problems. Original values, editable inputs, guided steps and checks.`)+`<section class="card"><div class="filters"><input id="examplequery" type="search" aria-label="Search worked examples" placeholder="Search title, page, type, difficulty…" value="${esc(exampleQuery)}"><select id="exampletype" aria-label="Filter example type"><option value="">All problem types</option>${Object.entries(labs).map(([k,v])=>`<option value="${k}" ${exampleType===k?'selected':''}>${v.title}</option>`).join('')}</select></div><p class="meta">${matches.length} examples · Source values are preserved. Problems with damaged overbars use minterm lists or explicitly transcribed notation.</p><div class="grid2">${matches.map(e=>`<article class="concept"><span class="source-badge">${e.source}</span><h3 style="margin-top:10px">${esc(e.title)}</h3><p class="meta">PDF ${e.page} · Printed ${P[e.page-1].printed??'—'} · ${esc(chapter(e.page)[0])}<br>${e.type} · ${e.difficulty}</p><p class="meta">Formula: ${esc(labs[e.type].rule)}</p><div class="actions"><button class="primary" data-example="${e.id}">Solve step by step →</button><button data-page="${e.page}">Source topic</button></div></article>`).join('')||'<p class="empty">No examples found. Try another keyword.</p>'}</div></section>`;$('#examplequery').onchange=()=>{exampleQuery=$('#examplequery').value;exampleView()};$('#exampletype').onchange=()=>{exampleType=$('#exampletype').value;exampleView()};bindExamples();bindPages();}
function chapterSelect(id,current=''){return `<select id="${id}" aria-label="Filter chapter"><option value="">All chapters</option>${C.map(([name],i)=>`<option value="${i}" ${String(current)===String(i)?'selected':''}>${esc(name)}</option>`).join('')}</select>`;}
function pool(){return questions.filter(q=>(qFilter===''||P[q.page-1].chapter===+qFilter)&&(!difficulty||q.difficulty===difficulty));}
function practiceView(){let qs=pool();qIndex=Math.min(qIndex,Math.max(0,qs.length-1));let q=qs[qIndex];$('#main').innerHTML=hero('PRACTICE WITH FEEDBACK','ভুল থেকেই শেখা শুরু।',`${questions.length} newly authored MCQs with source-topic references. Original PDF question banks remain available on pages 52–55.`)+`<section class="card"><div class="filters">${chapterSelect('qchapter',qFilter)}<select id="qdifficulty" aria-label="Filter difficulty"><option value="">All difficulty</option>${['Beginner','Intermediate'].map(x=>`<option ${difficulty===x?'selected':''}>${x}</option>`).join('')}</select></div><p class="meta">Attempted ${Object.keys(S.answers).length} · Correct ${questions.filter(q=>S.answers[q.id]===q.correct).length} · Incorrect ${questions.filter(q=>S.answers[q.id]!=null&&S.answers[q.id]!==q.correct).length}</p>${q?`<span class="source-badge">${q.source}</span><div class="meta">Question ${qIndex+1} / ${qs.length} · ${q.difficulty} · Source topic PDF ${q.page}</div><h2>${esc(q.q)}</h2>${q.options.map((o,i)=>`<button class="option ${selected===i?'selected':''} ${checked&&i===q.correct?'correct':''} ${checked&&selected===i&&i!==q.correct?'wrong':''}" data-answer="${i}" ${checked?'disabled':''}>${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}${checked?`<div class="callout" role="status"><b>${selected===q.correct?'✓ সঠিক উত্তর':'আরেকবার ভাবুন · Correct: '+String.fromCharCode(65+q.correct)}</b><p>${esc(q.explanation)}</p></div>`:''}<details class="concept"><summary>Reveal hint</summary><p>${esc(q.hint)}</p></details><div class="actions"><button id="qprev" ${qIndex===0?'disabled':''}>← Previous</button><button id="qretry">Retry</button><button class="primary" id="qnext" ${qIndex===qs.length-1?'disabled':''}>Next →</button><button data-page="${q.page}">Review source topic</button></div><div class="palette">${qs.map((item,i)=>`<button data-qindex="${i}" class="${S.answers[item.id]!=null?'answered':''}" aria-label="Question ${i+1}">${i+1}</button>`).join('')}</div>`:'<p class="empty">এই filter-এ MCQ নেই। Original bank বা অন্য chapter দেখুন।</p>'}</section>`;$('#qchapter').onchange=()=>{qFilter=$('#qchapter').value;qIndex=0;checked=false;selected=null;practiceView()};$('#qdifficulty').onchange=()=>{difficulty=$('#qdifficulty').value;qIndex=0;checked=false;selected=null;practiceView()};$$('[data-answer]').forEach(b=>b.onclick=()=>{selected=+b.dataset.answer;checked=true;S.answers[q.id]=selected;persist();practiceView()});function navigate(i){qIndex=i;selected=null;checked=false;practiceView();}if(q){$('#qprev').onclick=()=>navigate(qIndex-1);$('#qnext').onclick=()=>navigate(qIndex+1);$('#qretry').onclick=()=>navigate(qIndex);$$('[data-qindex]').forEach(b=>b.onclick=()=>navigate(+b.dataset.qindex));}bindPages();}
function mockView(){if(mock&&!mock.submitted){activeMock();return;}if(mock?.submitted&&showMockResults){mockResults();return;}$('#main').innerHTML=hero('YOUR OWN EXAM ROOM','সময় ধরে নিজেকে যাচাই করুন।','Choose chapters, question count and duration. These are practice tests, not an official examination pattern.')+`<section class="card"><h2>Configure your test</h2><form id="mock-config"><div class="formgrid"><label>Chapter${chapterSelect('mockchapter')}</label><label>Number of questions<input type="number" id="mock-count" min="1" max="${questions.length}" value="15" required></label><label>Duration (minutes)<input type="number" id="mock-minutes" min="1" max="180" value="15" required></label></div><div class="actions"><button class="primary">Start timed test →</button>${mock?.submitted?'<button type="button" id="last-result">View last result</button>':''}</div></form><div id="mock-error" role="alert"></div><p class="meta">Scoring: 1 per correct answer, 0 for incorrect or unanswered. No negative marking. Changing sections keeps an active test running; page reload ends the active session.</p></section>`;$('#mock-config').onsubmit=e=>{e.preventDefault();let ch=$('#mockchapter').value,count=+$('#mock-count').value,minutes=+$('#mock-minutes').value,pool=questions.filter(q=>ch===''||P[q.page-1].chapter===+ch);if(count>pool.length){$('#mock-error').innerHTML=`<div class="callout warning">এই selection-এ ${pool.length} প্রশ্ন আছে। Count কমান বা All chapters নিন।</div>`;return;}let shuffled=[...pool].sort(()=>Math.random()-.5);mock={qs:shuffled.slice(0,count),answers:{},review:[],deadline:Date.now()+minutes*60000,start:Date.now(),submitted:false};mockIdx=0;activeMock();};if($('#last-result'))$('#last-result').onclick=()=>{showMockResults=true;mockResults()};}
function timeLeft(){return mock?Math.max(0,Math.ceil((mock.deadline-Date.now())/1000)):0;}
function activeMock(){let q=mock.qs[mockIdx];$('#main').innerHTML=hero('TIMED PRACTICE · NOT AN OFFICIAL EXAM','আপনার পরীক্ষা চলছে।','উত্তর দিন, সন্দেহ থাকলে mark for review করুন। Timer সব section-এ চলতে থাকে।')+`<section class="card"><div class="cardhead"><span class="tag">Question ${mockIdx+1} / ${mock.qs.length}</span><span class="timer" id="timer" aria-label="Time remaining"></span></div><span class="source-badge">${q.source}</span><h2 style="margin-top:20px">${esc(q.q)}</h2>${q.options.map((o,i)=>`<button data-mock-answer="${i}" class="option ${mock.answers[q.id]===i?'selected':''}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}<div class="actions"><button id="mockprev" ${mockIdx===0?'disabled':''}>← Previous</button><button id="mock-review">${mock.review.includes(q.id)?'★ Marked':'☆ Mark for review'}</button><button id="mocknext" ${mockIdx===mock.qs.length-1?'disabled':''}>Next →</button><button class="primary" id="mocksubmit">Submit test</button></div><div class="palette">${mock.qs.map((x,i)=>`<button data-mock-index="${i}" class="${mock.answers[x.id]!=null?'answered':''} ${mock.review.includes(x.id)?'flag':''}">${i+1}</button>`).join('')}</div><small>Green = answered · Gold border = review · Timer expiry submits automatically.</small></section>`;updateTimer();$$('[data-mock-answer]').forEach(b=>b.onclick=()=>{mock.answers[q.id]=+b.dataset.mockAnswer;activeMock()});$('#mockprev').onclick=()=>{mockIdx--;activeMock()};$('#mocknext').onclick=()=>{mockIdx++;activeMock()};$('#mock-review').onclick=()=>{mock.review=mock.review.includes(q.id)?mock.review.filter(x=>x!==q.id):[...mock.review,q.id];activeMock()};$$('[data-mock-index]').forEach(b=>b.onclick=()=>{mockIdx=+b.dataset.mockIndex;activeMock()});$('#mocksubmit').onclick=()=>{dialog('Submit this test?',`<p>Answered ${Object.keys(mock.answers).length} of ${mock.qs.length}. Review-marked ${mock.review.length}.</p><div class="actions"><button id="confirm-submit" class="primary">Confirm submission</button><button id="continue-test">Continue test</button></div>`);$('#confirm-submit').onclick=()=>{$('#dialog').close();submitMock()};$('#continue-test').onclick=()=>$('#dialog').close();};}
function updateTimer(){if(!mock||mock.submitted)return;let secs=timeLeft();if($('#timer'))$('#timer').textContent=`${Math.floor(secs/60)}:${String(secs%60).padStart(2,'0')}`;if(!secs)submitMock();}
setInterval(updateTimer,1000);
function submitMock(){if(!mock||mock.submitted)return;mock.submitted=true;mock.used=Math.min(Date.now(),mock.deadline)-mock.start;mock.score=mock.qs.filter(q=>mock.answers[q.id]===q.correct).length;S.results.push({date:new Date().toISOString(),score:mock.score,total:mock.qs.length,seconds:Math.round(mock.used/1000)});persist();showMockResults=true;view='mock';shell();}
function mockResults(){let incorrect=mock.qs.filter(q=>mock.answers[q.id]!==q.correct);$('#main').innerHTML=hero('TEST COMPLETE','আপনার ফলাফল ও শেখার সুযোগ।',`Score ${mock.score}/${mock.qs.length} · Time used ${Math.floor(mock.used/60000)}m ${Math.floor(mock.used/1000)%60}s · Wrong/unanswered ${incorrect.length}`)+`<section class="card"><div class="actions"><button class="primary" id="retry-incorrect" ${incorrect.length?'':'disabled'}>Retry incorrect questions</button><button id="new-test">Configure new test</button></div>${mock.qs.map((q,i)=>`<div class="concept"><h3>${i+1}. ${esc(q.q)}</h3><p class="meta">Your answer: ${mock.answers[q.id]!=null?esc(q.options[mock.answers[q.id]]):'Unanswered'} · Correct: ${esc(q.options[q.correct])}</p><p>${esc(q.explanation)}</p><button data-page="${q.page}">Review topic · PDF ${q.page}</button></div>`).join('')}</section>`;$('#retry-incorrect').onclick=()=>{mock={qs:incorrect,answers:{},review:[],deadline:Date.now()+incorrect.length*60000,start:Date.now(),submitted:false};mockIdx=0;activeMock()};$('#new-test').onclick=()=>{showMockResults=false;mockView()};bindPages();}
let revChapter='',difficultOnly=false,revOrder=null;
function cards(){let list=P.flatMap(p=>p.points.map((text,i)=>({id:`${p.id}-${i}`,page:p.id,front:text.split(':')[0],back:text,term:p.title,bn:p.bn,memory:p.memory}))).filter(c=>(revChapter===''||P[c.page-1].chapter===+revChapter)&&(!difficultOnly||S.difficult.includes(c.page)));return revOrder?list.sort((a,b)=>(revOrder.indexOf(a.id)-revOrder.indexOf(b.id))):list;}
function revisionView(){let list=cards();flashIndex=Math.min(flashIndex,Math.max(0,list.length-1));let c=list[flashIndex];$('#main').innerHTML=hero('THE REVISION CENTER','মনে করুন। উল্টান। মিলিয়ে নিন।','Source-linked concept and formula recall cards. Mark difficult pages and return to them in short, regular sessions.')+`<section class="card"><div class="filters">${chapterSelect('revchapter',revChapter)}<button id="rev-difficult">${difficultOnly?'✓ ':''}Difficult topics only</button><button id="shuffle">Randomize</button></div>${c?`<p class="meta">Card ${flashIndex+1} / ${list.length} · ${S.learned.includes(c.id)?'✓ Learned':'Learning'} · PDF ${c.page}</p><button class="flash" id="flip" aria-label="Flip revision card"><div><small>${flipped?'ANSWER · উত্তর':'RECALL · মনে করুন'}</small><h2>${esc(flipped?c.back:c.front)}</h2><p>${esc(flipped?c.memory:c.bn)}</p><small>${flipped?'Click to hide answer':'Click to reveal answer'}</small></div></button><div class="actions"><button id="revprev" ${flashIndex===0?'disabled':''}>← Previous</button><button class="primary" id="learncard">${S.learned.includes(c.id)?'✓ Learned · Undo':'Mark as learned'}</button><button id="revbookmark">${S.marks.includes(c.page)?'★ Bookmarked':'☆ Bookmark topic'}</button><button id="revnext" ${flashIndex===list.length-1?'disabled':''}>Next →</button><button data-page="${c.page}">Read topic</button></div>`:'<p class="empty">এই filter-এ card নেই। Topic-এ Needs revision চাপুন বা filter বদলান।</p>'}</section>`;$('#revchapter').onchange=()=>{revChapter=$('#revchapter').value;flashIndex=0;flipped=false;revisionView()};$('#rev-difficult').onclick=()=>{difficultOnly=!difficultOnly;flashIndex=0;revisionView()};$('#shuffle').onclick=()=>{revOrder=list.map(x=>x.id).sort(()=>Math.random()-.5);flashIndex=0;flipped=false;revisionView()};if(c){$('#flip').onclick=()=>{flipped=!flipped;revisionView()};$('#revprev').onclick=()=>{flashIndex--;flipped=false;revisionView()};$('#revnext').onclick=()=>{flashIndex++;flipped=false;revisionView()};$('#learncard').onclick=()=>{toggle('learned',c.id);revisionView()};$('#revbookmark').onclick=()=>{toggle('marks',c.page);revisionView()};}bindPages();}
function dashboardView(){$('#main').innerHTML=hero('YOUR PERSONAL LEARNING JOURNEY','আজ একটু, কাল আরও এগিয়ে।','Progress, notes and results stay on this browser. Export a backup to keep your learning safe.')+`<div class="grid3">${[[S.done.length+'/55','Pages completed'],[Object.keys(S.answers).length+'/'+questions.length,'MCQs attempted'],[S.results.length,'Mock tests finished']].map(([n,t])=>`<div class="card"><span class="stat">${n}</span><small>${t}</small></div>`).join('')}</div><section class="card"><h2>Chapter progress</h2>${C.map(([name,start,end])=>{let count=S.done.filter(p=>p>=start&&p<=end).length;return `<div class="concept"><h3>${esc(name)}</h3><div class="track"><i style="width:${count/(end-start+1)*100}%"></i></div><small>${count}/${end-start+1} pages · ${Math.round(count/(end-start+1)*100)}%</small><button data-page="${start}" style="float:right">Continue →</button></div>`}).join('')}<div class="actions"><button id="export">Export study data</button><label class="tag">Import backup<input type="file" id="import" accept="application/json" style="font-size:11px"></label></div><p class="meta">Local data may be lost when browser data is cleared. Import merges notes and completion; no account or cloud sync. Active tests are not saved across reloads.</p><p id="import-result" role="status"></p></section><div class="grid2"><section class="card"><h3>Mock-test history</h3>${S.results.slice().reverse().map(r=>`<div class="concept">${new Date(r.date).toLocaleDateString('en-GB',{timeZone:'Asia/Dhaka'})} · <b>${r.score}/${r.total}</b></div>`).join('')||'<p class="empty">No tests yet. Start your first mock.</p>'}</section><section class="card"><h3>Difficult pages & bookmarks</h3>${[...new Set([...S.difficult,...S.marks])].map(id=>`<button class="option" data-page="${id}">PDF ${id} · ${esc(P[id-1].title)}</button>`).join('')||'<p class="empty">Save a topic to find it here.</p>'}</section></div>`;$('#export').onclick=()=>{let url=URL.createObjectURL(new Blob([JSON.stringify(S,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='it-path-study-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#import').onchange=async()=>{try{let f=$('#import').files[0];if(!f)return;if(f.size>2e6)throw Error('Backup file is too large.');let raw=JSON.parse(await f.text());if(raw.version!==1)throw Error('Unsupported backup version.');let x=validate(raw);for(let k of ['done','marks','difficult','learned'])S[k]=[...new Set([...S[k],...x[k]])];S.notes={...S.notes,...x.notes};S.answers={...S.answers,...x.answers};S.results=[...S.results,...x.results].filter((v,i,a)=>a.findIndex(z=>z.date===v.date)===i).slice(-100);persist();shell();toast('Study backup imported ✓');}catch(e){$('#import-result').textContent='Import failed: '+e.message;}};bindPages();}
function coverageView(){$('#main').innerHTML=hero('SOURCE INTEGRITY & COVERAGE','প্রতিটি পৃষ্ঠা আছে। যাচাইয়ের সীমাও স্পষ্ট।','55 original pages preserved, page-level study notes mapped, and source issues disclosed. This is not a claim of complete line-by-line instructional coverage.')+`<section class="card"><div class="callout warning"><b>Verification status</b><br>All pages were extracted and visually surveyed as contact sheets. Formula overbars are unreliable in plain text. Source images are authoritative. Page-level bilingual notes and reading modes exist, but some sections still need deeper, topic-specific teaching, and not every original question has an interactive answer. No 100% completeness claim.</div><div class="actions"><a href="/book.pdf" target="_blank" rel="noopener">Original PDF · 55 pages ↗</a><a href="/data/coverage.json" download>Download coverage report</a></div><h2>Chapter index</h2><div class="scroll"><table class="data"><tr><th>Chapter</th><th>PDF pages</th><th>Printed pages</th></tr>${C.map(([name,start,end])=>`<tr><td>${esc(name)}</td><td>${start}–${end}</td><td>${P[start-1].printed??'unnumbered'}–${P[end-1].printed??'unnumbered'}</td></tr>`).join('')}</table></div></section><section class="card"><h2>Source corrections / qualifications · ${issues.length}</h2>${issues.map(([page,original,correction])=>`<div class="concept"><span class="tag">PDF ${page}</span><p><b>Original:</b> ${esc(original)}</p><p><b>Correction:</b> ${esc(correction)}</p><button data-page="${page}">Open page</button></div>`).join('')}</section><section class="card"><h2>Page-by-page coverage</h2><div class="scroll"><table class="data"><tr><th>PDF / printed</th><th>Topic</th><th>Status</th></tr>${coverage.map(p=>`<tr><td><button data-page="${p.pdf_page}">${p.pdf_page} / ${p.printed_page??'—'}</button></td><td>${esc(p.topic)}</td><td>Source ✓ · Page lesson ✓<br><small>${esc(p.verification)}</small></td></tr>`).join('')}</table></div></section>`;bindPages();}
function highlight(text,q){let s=String(text),idx=s.toLowerCase().indexOf(q.toLowerCase());if(idx<0)return esc(s);return esc(s.slice(0,idx))+'<mark>'+esc(s.slice(idx,idx+q.length))+'</mark>'+esc(s.slice(idx+q.length));}
function search(query){let q=query.trim();if(!q)return;let type='all';function show(){let records=[...P.map(p=>({type:'topic',title:p.title+' · '+p.bn,text:p.intro+' '+p.points.join(' ')+' '+p.text,page:p.id})),...questions.map(x=>({type:'question',title:x.q,text:x.explanation+' '+x.options.join(' '),page:x.page})),...examples.map(x=>({type:'example',title:x.title,text:labs[x.type].rule+' '+x.type,page:x.page,id:x.id}))].filter(x=>(type==='all'||x.type===type)&&(x.title+' '+x.text).toLowerCase().includes(q.toLowerCase()));dialog('Search academy',`<div class="filters"><input id="search-again" value="${esc(q)}" aria-label="Search keywords"><select id="searchtype" aria-label="Content type">${['all','topic','question','example'].map(x=>`<option ${type===x?'selected':''}>${x}</option>`).join('')}</select><button id="search-run">Search</button></div><p class="meta">${records.length} results · Suggestions: Linux, permission, binary, K-map, testing, সংখ্যা</p>${records.map(x=>{let index=x.text.toLowerCase().indexOf(q.toLowerCase()),snippet=x.text.slice(Math.max(0,index-50),Math.max(0,index-50)+200);return `<article class="concept"><span class="tag">${x.type} · PDF ${x.page}</span><h3 style="margin-top:12px">${highlight(x.title,q)}</h3><p style="font-size:13px">${highlight(snippet,q)}</p><button ${x.type==='example'?`data-search-example="${x.id}"`:`data-page="${x.page}"`}>Open ${x.type} →</button></article>`}).join('')||'<p class="empty">কিছু পাওয়া যায়নি। বাংলা বা English-এ ছোট keyword দিন।</p>'}`);$('#searchtype').onchange=()=>{type=$('#searchtype').value;show()};$('#search-run').onclick=()=>{q=$('#search-again').value.trim();if(q)show()};$('#search-again').onkeydown=e=>{if(e.key==='Enter'){q=e.target.value.trim();if(q)show()}};bindPages($('#dialog-body'));$$('[data-search-example]').forEach(b=>b.onclick=()=>{$('#dialog').close();openExample(+b.dataset.searchExample)});}show();}
let diagram='gates',gateA=0,gateB=1,gateCin=0,muxSelect=0;
function diagramView(){$('#main').innerHTML=hero('SEE THE CONCEPT IN ACTION','ছবি দেখে যুক্তিটা ধরুন।','Change a bit, follow a process, or click a layer. Each diagram teaches a concept from the book.')+`<div class="filters"><select id="diagram-select" aria-label="Choose diagram">${[['gates','Logic gates & full adder'],['mux','4:1 multiplexer'],['linux','Linux architecture'],['sdlc','SDLC flow'],['flip','Flip-flop behaviour'],['circuit','K-map to AND–OR circuit']].map(([k,t])=>`<option value="${k}" ${diagram===k?'selected':''}>${t}</option>`).join('')}</select></div><section class="card" id="diagram-body"></section>`;$('#diagram-select').onchange=()=>{diagram=$('#diagram-select').value;drawDiagram()};drawDiagram();}
function drawDiagram(){let area=$('#diagram-body');if(diagram==='gates'){let rows=[['AND',gateA&gateB],['OR',gateA|gateB],['NAND',1-(gateA&gateB)],['NOR',1-(gateA|gateB)],['XOR',gateA^gateB],['XNOR',1-(gateA^gateB)],['NOT A',1-gateA]];area.innerHTML=`<h2>Logic gate playground</h2><p>একটি bit বদলে output দেখুন। Output একই input থেকে live হিসাব হয়।</p><div class="actions"><button id="gate-a">A = ${gateA} · Toggle</button><button id="gate-b">B = ${gateB} · Toggle</button><button id="gate-c">Cin = ${gateCin} · Toggle</button></div><div class="grid3">${rows.map(([name,v])=>`<div class="concept"><small>${name}</small><span class="stat">${v}</span><p class="meta">Input A=${gateA}, B=${gateB}</p></div>`).join('')}</div><div class="callout"><b>Full adder</b><br>Sum = A ⊕ B ⊕ Cin = ${gateA^gateB^gateCin}<br>Carry = AB + ACin + BCin = ${(gateA&gateB)|(gateA&gateCin)|(gateB&gateCin)}<br>Decimal check: ${gateA}+${gateB}+${gateCin} = ${gateA+gateB+gateCin}</div>`;$('#gate-a').onclick=()=>{gateA=1-gateA;drawDiagram()};$('#gate-b').onclick=()=>{gateB=1-gateB;drawDiagram()};$('#gate-c').onclick=()=>{gateCin=1-gateCin;drawDiagram()};}
if(diagram==='mux'){area.innerHTML=`<h2>4:1 MUX · select one input</h2><p>দুটি select bit ${math('S_1S_0')} চারটি input-এর একটি বেছে নেয়।</p><label>Select S1S0<select id="mux-select">${[0,1,2,3].map(i=>`<option value="${i}" ${muxSelect===i?'selected':''}>${i.toString(2).padStart(2,'0')}</option>`).join('')}</select></label><div class="diagram-flow">${[0,1,2,3].map(i=>`<button data-mux="${i}" class="${i===muxSelect?'primary':''}">I${i} ${i===muxSelect?'→ Y':'—'}</button>`).join('')}</div><div class="callout">Y = I${muxSelect}. Select value ${muxSelect.toString(2).padStart(2,'0')} means input ${muxSelect}.<br>${math(String.raw`Y=\bar S_1\bar S_0 I_0+\bar S_1 S_0 I_1+S_1\bar S_0 I_2+S_1S_0 I_3`)}</div>`;$('#mux-select').onchange=()=>{muxSelect=+$('#mux-select').value;drawDiagram()};$$('[data-mux]').forEach(b=>b.onclick=()=>{muxSelect=+b.dataset.mux;drawDiagram()});}
if(['linux','sdlc'].includes(diagram)){let data=diagram==='linux'?[['Hardware','Physical CPU, RAM, disk, input/output devices.'],['Kernel','Process scheduling, memory management ও device access নিয়ন্ত্রণ করে।'],['Shell','Command interpreter—আপনার নির্দেশ গ্রহণ করে program চালায়।'],['Applications','User-এর কাজের tools: editor, browser, compiler।'],['User','আপনি applications ও shell দিয়ে system ব্যবহার করেন।']]:[['Planning','Stakeholder need, feasibility ও project risk বুঝুন।'],['Requirements','SRS-এ স্পষ্ট, যাচাইযোগ্য requirements লিখুন।'],['Design','Architecture, modules, interfaces ও data design করুন।'],['Development','Design অনুযায়ী code ও unit checks করুন।'],['Testing','Unit, integration, system ও acceptance test করুন।'],['Deployment','ব্যবহারযোগ্য environment-এ release করুন।'],['Maintenance','Fault ঠিক করুন, change ও নতুন environment সামলান।']];area.innerHTML=`<h2>${diagram==='linux'?'Linux architecture · ভিতর থেকে বাইরে':'SDLC · প্রয়োজন থেকে রক্ষণাবেক্ষণ'}</h2><div class="diagram-flow">${data.map(([name],i)=>`<button data-node="${i}">${i+1}. ${name}</button>`).join(' → ')}</div><p class="callout" id="node-detail">${esc(data[0][1])}</p><small>Click a node for its role. This is a conceptual sequence; real systems may overlap layers/phases.</small>`;$$('[data-node]').forEach(b=>b.onclick=()=>$('#node-detail').textContent=data[+b.dataset.node][1]);}
if(diagram==='flip'){area.innerHTML=`<h2>Flip-flop next state</h2><form id="flip-form"><div class="formgrid"><label>Type<select name="kind"><option>JK</option><option>D</option><option>T</option><option>SR</option></select></label><label>Current Q<select name="q"><option>0</option><option>1</option></select></label><label>Input 1 (J / D / T / S)<select name="a"><option>0</option><option>1</option></select></label><label>Input 2 (K / R)<select name="b"><option>0</option><option>1</option></select></label></div></form><div class="callout" id="flip-output" role="status"></div><p class="meta">Ideal active-high next-state model. SR 11 invalid; D/T ignore second input.</p>`;let calc=()=>{let {kind,q,a,b}=Object.fromEntries(new FormData($('#flip-form')));q=+q;a=+a;b=+b;let result=kind==='D'?a:kind==='T'?a^q:kind==='SR'?(a&&b?'INVALID':a?1:b?0:q):((a&(1-q))|((1-b)&q));$('#flip-output').textContent=`At the next active clock edge: Q(next) = ${result}`;};$('#flip-form').onchange=calc;calc();}
if(diagram==='circuit'){area.innerHTML=`<h2>JBL source example · PDF 28</h2><p>F = A′C′ + B′C′ + BC। তিনটি product term-এর জন্য তিনটি AND gate, শেষে একটি OR gate।</p><svg viewBox="0 0 580 250" style="width:100%" role="img" aria-label="A prime C prime and B prime C prime and BC feed three AND gates into an OR output"><g fill="none" stroke="currentColor" stroke-width="2"><path d="M95 50h70m-70 75h70m-70 75h70M255 50h65v75h75m-140 0h140m-140 75h65v-75M485 125h65"/><rect x="165" y="25" width="90" height="50" rx="18"/><rect x="165" y="100" width="90" height="50" rx="18"/><rect x="165" y="175" width="90" height="50" rx="18"/><rect x="395" y="100" width="90" height="50" rx="18"/></g><g fill="currentColor" font-family="sans-serif" font-size="17"><text x="15" y="55">A′, C′</text><text x="15" y="130">B′, C′</text><text x="15" y="205">B, C</text><text x="190" y="55">AND</text><text x="190" y="130">AND</text><text x="190" y="205">AND</text><text x="425" y="131">OR</text><text x="555" y="131">F</text></g></svg><button id="circuit-solve" class="primary">Verify every truth-table row →</button>`;$('#circuit-solve').onclick=()=>openExample(examples.find(e=>e.title==='JBL K-map and circuit').id);}}
let originalBank=null,bankQuery='',bankPage='';
async function writtenView(){if(!originalBank){try{originalBank=await fetch('/data/original-bank.json').then(r=>r.json());}catch{$('#main').innerHTML='<p class="empty">Original question bank load হয়নি। আবার চেষ্টা করুন।</p>';return;}}let list=originalBank.filter(q=>(!bankPage||String(q.page)===bankPage)&&(q.question+' '+q.answer).toLowerCase().includes(bankQuery.toLowerCase()));$('#main').innerHTML=hero('PDF ORIGINAL QUESTION BANK','মূল প্রশ্ন। নিজের উত্তর। তারপর মিলিয়ে নিন।',`${originalBank.length} original source rows from PDF pages 52–55. Wording is extracted, not rewritten into invented original MCQs.`)+`<section class="card"><div class="filters"><input id="bankquery" aria-label="Search original questions" placeholder="Search original question or answer…" value="${esc(bankQuery)}"><select id="bankpage" aria-label="Filter source page"><option value="">All bank pages</option>${[52,53,54,55].map(p=>`<option ${bankPage===String(p)?'selected':''}>${p}</option>`).join('')}</select></div><div class="callout warning">Original answers may contain source errors. Complement bars can disappear in text extraction. Always compare mathematical notation with the page image and use the corrected Math lab or Source audit. These rows are not certified transcriptions.</div>${list.map(q=>`<article class="concept"><span class="source-badge">${q.source} · PDF ${q.page} / Printed ${P[q.page-1].printed}</span><h3 style="margin-top:13px">${esc(q.question)}</h3><details class="concept"><summary>Reveal original answer</summary><p>${esc(q.answer)}</p><small>${q.verification}</small></details><button data-bank-source="${q.page}">Compare original page ↗</button></article>`).join('')||'<p class="empty">কিছু পাওয়া যায়নি। Keyword বদলান।</p>'}</section>`;$('#bankquery').onchange=()=>{bankQuery=$('#bankquery').value;writtenView()};$('#bankpage').onchange=()=>{bankPage=$('#bankpage').value;writtenView()};$$('[data-bank-source]').forEach(b=>b.onclick=()=>source(+b.dataset.bankSource));}
shell();if(storageWarning)toast(storageWarning);
